import {escapeHtml as esc} from './message-format.js';
import {localInstant,localAt as localAtMs} from './oncall-planning.js';
const localAt=(ns,zone)=>localAtMs(Number(ns/1000000n),zone);
const k=v=>Object.keys(v)[0];
const input=(name,title,value='',attrs='')=>`<label>${esc(title)}<input name="${name}" value="${esc(value)}" ${attrs}></label>`;
const select=(name,title,value,options)=>`<label>${esc(title)}<select name="${name}">${options.map(([v,t])=>`<option value="${v}" ${String(value)===v?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;
export const credit=n=>`${n < 0n?'−':''}${Number(n < 0n?-n:n)/60 % 1===0?String((n < 0n?-n:n)/60n)+' h':String(n < 0n?-n:n)+' min'}`;
export function calculationHTML(calculation,money){
 const ls=calculation.lines,r=calculation.rule[0];
 if(!ls.length&&!r)return '';
 const people=new Map();for(const l of ls){let row=people.get(l.personId);if(!row){row={name:l.name,money:0n,minutes:0n,currency:l.currency,decimals:l.decimals};people.set(l.personId,row);}if(k(l.unit)==='money'){row.money+=l.amount;row.currency=l.currency;row.decimals=l.decimals;}else row.minutes+=l.amount;}
 return `<section class="card rp-calculation"><div class="section-heading"><h3>Reviewed calculation</h3><span class="kv">Money and time stay separate</span></div>${people.size?`<div class="rp-table"><table><thead><tr><th>Person</th><th>Money</th><th>Time credit</th></tr></thead><tbody>${[...people.values()].map(p=>`<tr><td><strong>${esc(p.name)}</strong></td><td>${p.currency?`${esc(p.currency)} ${money(p.money,p.decimals)}`:'—'}</td><td>${p.minutes?credit(p.minutes):'—'}</td></tr>`).join('')}</tbody></table></div>`:''}<details><summary>How this is calculated · ${ls.length} daily lines${r?' · rule '+r.revision:''}</summary>${r?`<p class="kv">${esc(r.timezone)} · ${k(r.readinessBasis)==='day'?'Readiness: a full local day earns one allowance; partial days share it proportionally.':'Readiness: recorded hours × layer rate.'} Work: daily total after breaks, minimum ${r.minimumMinutes} min, rounded up to ${r.roundingMinutes} min. Holiday rates replace weekend and weekday rates. Readiness and work are additive.</p>`:''}${ls.length?`<div class="rp-table"><table><thead><tr><th>Person / day</th><th>Calculation</th><th>Money</th><th>Time credit</th></tr></thead><tbody>${ls.map(l=>`<tr><td><strong>${esc(l.name)}</strong><span class="rowsub">${esc(l.date||'Linked correction')}${l.date?' · '+esc(k(l.dayKind)):''}</span><span class="rowsub">${esc(l.code)}</span></td><td>${k(l.basis)==='adjustment'?'Signed correction':`${(Number(l.seconds)/3600).toFixed(2)} h recorded${l.payableSeconds!==l.seconds?` → ${(Number(l.payableSeconds)/3600).toFixed(2)} h payable`:''}<span class="rowsub">${k(l.basis)==='day'?`${(Number(l.divisorSeconds)/3600).toFixed(0)} h local day · `:''}${k(l.unit)==='money'?`${esc(l.currency)} ${money(l.rate,l.decimals)}`:`${l.rate} min`} / ${k(l.basis)}</span>`}<span class="rowsub">Rule ${l.ruleRevision} · records ${l.recordIds.map(String).join(', ')}</span></td><td>${k(l.unit)==='money'?`${esc(l.currency)} ${money(l.amount,l.decimals)}`:'—'}</td><td>${k(l.unit)==='minutes'?credit(l.amount):'—'}</td></tr>`).join('')}</tbody></table></div>`:'<p>Approved service records appear here with their calculation. Pending records are not included.</p>'}</details></section>`;
}
export function renderCompensationEditor({root,p,history,periods,api,token,action,notice,money,parseMoney}){
 const $=s=>root.querySelector(s),activeRules=history.rules.filter(r=>!r.withdrawnAt),saved=activeRules.at(-1),base=saved?.policy||p.policy[0],digits=Number(base?.decimals??2n),zone=saved?.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC';
 const now=new Date(),next=new Date(Date.UTC(now.getFullYear(),now.getMonth()+1,1)).toISOString().slice(0,10),first=new Date(Date.UTC(now.getFullYear(),now.getMonth(),1)).toISOString().slice(0,10);
 const ends=periods.filter(x=>x.projectId===p.id).map(x=>x.endAt),latestEnd=ends.reduce((a,b)=>a>b?a:b,0n),after=latestEnd?localAt(latestEnd,zone).slice(0,10):first;
 const savedDay=saved?localAt(saved.effectiveAt,zone).slice(0,10):'',following=savedDay?new Date(Date.UTC(Number(savedDay.slice(0,4)),Number(savedDay.slice(5,7)),1)).toISOString().slice(0,10):'';
 const effective=saved?[next,after,following].sort().at(-1):[after,first].sort().at(-1);
 const rates=saved?.readiness||base?.readinessRates.map(n=>({weekday:n,weekend:n,holiday:n}))||[],work=saved?.work||{weekday:base?.workRate,weekend:base?.workRate,holiday:base?.workRate};
 const unitChoices=[['money','Money'],['minutes','Time credit · minutes']];
 const amount=(n,u)=>n===undefined?'':k(u)==='minutes'?String(n):money(n,digits);
 root.innerHTML=`<a class="back-link" href="#/reporting/project-${p.id}">← ${esc(p.name)}</a><div class="page-heading"><div><span class="eyebrow">ON-CALL / REPORTING · ALPHA</span><h2>${saved?'Schedule new compensation rules':'Set up compensation'}</h2><p class="lead">Set company rates. Check a few examples. Start from a known date.</p></div></div>${history.rules.length?`<details class="card"><summary>Rule history · ${history.rules.length} version${history.rules.length===1?'':'s'}</summary>${history.rules.slice().reverse().map(r=>`<p><strong>Rule ${r.revision}</strong> · ${esc(localAt(r.effectiveAt,r.timezone).slice(0,10))} · ${esc(r.timezone)} <span class="pill">${r.withdrawnAt?'Withdrawn':r.effectiveAt>BigInt(Date.now())*1000000n?'Scheduled':r===activeRules.filter(x=>x.effectiveAt<=BigInt(Date.now())*1000000n).at(-1)?'Current':'Previous'}</span>${!r.withdrawnAt&&r.effectiveAt>BigInt(Date.now())*1000000n?` <button class="sm" data-withdraw="${r.revision}">Withdraw unused rule</button>`:''}</p>`).join('')}</details>`:base?'<p class="rp-callout">Existing statements keep their hourly rules. These dated rules apply to new statements from the date below.</p>':''}<form id="rpRules" class="rp-form"><section class="card"><span class="eyebrow">01 / WHEN</span><h3>A clear starting point</h3><div class="row">${input('effective','Effective from · local midnight',effective,'type="date" required')}${input('zone','Reporting timezone',zone,'required')}</div><p class="kv">One company calendar for this project. A rule change starts a new statement; existing statements keep their snapshot.</p></section><section class="card"><span class="eyebrow">02 / READINESS</span><h3>Being available</h3><div class="row">${select('basis','Pay basis',rates.length?k(saved?.readinessBasis||{hour:null}):base?'none':'day',[['none','Actual work only'],['hour','Per readiness hour'],['day','Per full local day']])}${select('readinessUnit','Reward',k(saved?.readinessUnit||{money:null}),unitChoices)}${select('layers','Response layers',String(rates.length||2),Array.from({length:6},(_,i)=>[String(i+1),String(i+1)]))}</div><div id="rpRates"></div><p class="kv" data-readiness-help></p></section><section class="card"><span class="eyebrow">03 / ACTUAL WORK</span><h3>Time spent responding</h3>${select('workUnit','Reward',k(saved?.workUnit||{money:null}),unitChoices)}<div class="row">${['weekday','weekend','holiday'].map(t=>input('work-'+t,t[0].toUpperCase()+t.slice(1)+' rate / hour',amount(work[t],saved?.workUnit||{money:null}),'inputmode="decimal" required')).join('')}</div><details><summary>Minimum duration & rounding</summary><div class="row">${input('minimum','Minimum per person / local day · minutes',saved?.minimumMinutes??0n,'type="number" min="0" max="1440" required')}${select('rounding','Round daily total up to',String(saved?.roundingMinutes??1n),[1,5,6,10,15,30,60].map(n=>[String(n),n+' minute'+(n===1?'':'s')]))}</div><p class="kv">Add up all approved work after breaks, then apply the minimum once per person and day. Splitting entries does not multiply the minimum. This is not a per-callout minimum.</p></details></section><details class="card" ${base?'':'open'}><summary>Calendar & payroll details</summary><div class="row">${input('currency','Currency',base?.currency||'','required pattern="[A-Z]{3}" maxlength="3" placeholder="CHF"')}${input('digits','Currency decimal places',digits,'type="number" min="0" max="3" required')}</div><label>Company holidays · one ISO date per line<textarea name="holidays" rows="3" placeholder="2026-12-25">${esc(saved?.holidays.join('\n')||'')}</textarea></label><p class="kv">Saturdays and Sundays use the weekend rate. Listed holidays use the holiday rate even on a weekend. Dates are explicit; national calendars and legal supplements are not inferred.</p><div class="row">${input('readinessCode','Readiness payroll code',base?.readinessCode||'','required maxlength="40"')}${input('workCode','Work payroll code',base?.workCode||'','required maxlength="40"')}</div><div class="row">${input('costCenter','Cost center',base?.costCenter||'','maxlength="80"')}${input('retention','Delete statements after period end · days',base?.retentionDays||'','type="number" min="30" max="3650" required')}</div><p class="kv">Time credits are whole minutes, kept separate from money. Validate company rules with your payroll team.</p></details><div class="btnrow"><button class="primary">Check example calculations</button><a class="button" href="#/reporting/project-${p.id}">Cancel</a></div></form><p data-rp-status role="status" aria-live="polite"></p><div id="rpExamples"></div>`;
 let formRevision=0;
 let preserved=rates.map(r=>Object.fromEntries(Object.entries(r).map(([t,n])=>[t,amount(n,saved?.readinessUnit||{money:null})])));
 function readiness(){const n=Number($('[name="layers"]').value),mode=$('[name="basis"]').value,unit=$('[name="readinessUnit"]').value;root.querySelectorAll('[data-rate]').forEach(el=>{const [i,t]=el.dataset.rate.split(':');(preserved[i]??={})[t]=el.value;});$('#rpRates').innerHTML=mode==='none'?'':Array.from({length:n},(_,i)=>`<div class="rp-rate-layer"><strong>${i===0?'Primary':i===1?'Backup':'Layer '+(i+1)}</strong><div class="row">${['weekday','weekend','holiday'].map(t=>input(`r${i}-${t}`,t[0].toUpperCase()+t.slice(1),preserved[i]?.[t]??'',`data-rate="${i}:${t}" inputmode="decimal" required`)).join('')}</div></div>`).join('');for(const name of ['readinessUnit','layers'])$(`[name="${name}"]`).closest('label').hidden=mode==='none';$('[data-readiness-help]').textContent=mode==='none'?'Only actual work will be imported.':`${unit==='minutes'?'Minutes of time credit':'Currency amount'} per ${mode==='day'?'full local day. Part-days are proportional; 23- and 25-hour days each count as one day.':'hour of readiness.'}`;}
 readiness();for(const name of ['layers','basis','readinessUnit'])$(`[name="${name}"]`).onchange=readiness;
 $('#rpRules').addEventListener('input',()=>{formRevision++;$('#rpExamples').replaceChildren();});$('#rpRules').addEventListener('change',()=>{formRevision++;$('#rpExamples').replaceChildren();});
 $('#rpRules').onsubmit=e=>{e.preventDefault();action(e.submitter,async()=>{const checkedRevision=formRevision,f=new FormData(e.currentTarget),d=Number(f.get('digits'));const readUnit=f.get('readinessUnit'),workUnit=f.get('workUnit');const number=(v,u)=>{const n=parseMoney(v,u==='minutes'?0:d);if(n<0n)throw Error('Rates cannot be negative.');return n;};const triple=(prefix,u)=>Object.fromEntries(['weekday','weekend','holiday'].map(t=>[t,number(f.get(prefix+t),u)]));const readiness=f.get('basis')==='none'?[]:Array.from({length:Number(f.get('layers'))},(_,i)=>triple(`r${i}-`,readUnit)),work=triple('work-',workUnit);const draft={policy:{currency:f.get('currency'),decimals:BigInt(d),readinessRates:readiness.map(r=>r.weekday),workRate:work.weekday,readinessCode:f.get('readinessCode'),workCode:f.get('workCode'),costCenter:f.get('costCenter'),retentionDays:BigInt(f.get('retention'))},effectiveAt:localInstant(f.get('effective')+'T00:00',f.get('zone')),timezone:f.get('zone'),holidays:[...new Set(f.get('holidays').split(/[\s,]+/).filter(Boolean))],readinessBasis:{[f.get('basis')==='day'?'day':'hour']:null},readinessUnit:{[readUnit]:null},readiness,workUnit:{[workUnit]:null},work,minimumMinutes:BigInt(f.get('minimum')),roundingMinutes:BigInt(f.get('rounding'))};const r=await api().previewReportingCompensation(token(),p.id,draft);if(r.err)throw Error(r.err);return {ok:{draft,examples:r.ok,checkedRevision}};},({draft,examples,checkedRevision})=>{
 if(checkedRevision!==formRevision){notice('Rules changed while calculating. Check the examples again.');return;}
 $('#rpExamples').innerHTML=`<section class="card rp-example"><span class="eyebrow">04 / CHECK & ACTIVATE</span><h3>No surprises on payday.</h3><p>Examples from the server calculation. Start: <strong>${esc(localAt(draft.effectiveAt,draft.timezone).slice(0,10))}</strong> · ${esc(draft.timezone)}.</p><div class="rp-table"><table><thead><tr><th>Example</th><th>Payable</th><th>Result</th></tr></thead><tbody>${examples.map(x=>`<tr><td>${esc(x.title)}</td><td>${Number(x.payableSeconds)/60} min</td><td><strong>${k(x.unit)==='money'?`${esc(draft.policy.currency)} ${money(x.amount,draft.policy.decimals)}`:credit(x.amount)}</strong></td></tr>`).join('')}</tbody></table></div><p class="kv">Daily totals round once per person, service type and readiness layer. Readiness and actual work are additive. The rule author cannot release a statement calculated with this rule.</p><form id="rpActivate"><label class="checkline"><input type="checkbox" required> I checked these rules against our company agreement.</label><button class="primary">Activate from ${esc(localAt(draft.effectiveAt,draft.timezone).slice(0,10))}</button></form></section>`;
 $('#rpActivate').onsubmit=ev=>{ev.preventDefault();action(ev.submitter,()=>api().activateReportingCompensation(token(),p.id,history.revision,draft),()=>{location.hash=`#/reporting/project-${p.id}`;});};$('#rpExamples').scrollIntoView?.({block:'start'});notice('Examples ready. Nothing has been activated yet.');
 });};
 root.querySelectorAll('[data-withdraw]').forEach(b=>b.onclick=()=>action(b,()=>api().withdrawReportingCompensation(token(),p.id,history.revision,BigInt(b.dataset.withdraw))));
}
